struct FStreamingSourceShape final
{
public:
	bool                                          bUseGridLoadingRange;
	uint8                                         Pad_1[0x3];
	float                                         LoadingRangeScale;
	float                                         Radius;
	bool                                          bIsSector;
	uint8                                         Pad_D[0x3];
	float                                         SectorAngle;
	uint8                                         Pad_14[0x4];
	struct FVector                                Location;
	struct FRotator                               Rotation;
};
static_assert(alignof(FStreamingSourceShape) == 0x000008, "Wrong alignment on FStreamingSourceShape");
static_assert(sizeof(FStreamingSourceShape) == 0x000048, "Wrong size on FStreamingSourceShape");
static_assert(offsetof(FStreamingSourceShape, bUseGridLoadingRange) == 0x000000, "Member 'FStreamingSourceShape::bUseGridLoadingRange' has a wrong offset!");
static_assert(offsetof(FStreamingSourceShape, LoadingRangeScale) == 0x000004, "Member 'FStreamingSourceShape::LoadingRangeScale' has a wrong offset!");
static_assert(offsetof(FStreamingSourceShape, Radius) == 0x000008, "Member 'FStreamingSourceShape::Radius' has a wrong offset!");
static_assert(offsetof(FStreamingSourceShape, bIsSector) == 0x00000C, "Member 'FStreamingSourceShape::bIsSector' has a wrong offset!");
static_assert(offsetof(FStreamingSourceShape, SectorAngle) == 0x000010, "Member 'FStreamingSourceShape::SectorAngle' has a wrong offset!");
static_assert(offsetof(FStreamingSourceShape, Location) == 0x000018, "Member 'FStreamingSourceShape::Location' has a wrong offset!");
static_assert(offsetof(FStreamingSourceShape, Rotation) == 0x000030, "Member 'FStreamingSourceShape::Rotation' has a wrong offset!");

